#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int dis[] = {1, 2, 3, 4, 5, 6, 7, 8, 9, 89, 135, 175, 518, 598, 1306, 1676, 2427};
    int first = 1;
    for (int i = 0; i < 17; i++) {
        if (dis[i] <= n) {
            if (!first) printf(" ");
            printf("%d", dis[i]);
            first = 0;
        }
    }
    printf("\n");
    return 0;
}

