        const n = parseInt(toks[0], 10);
        const dis = [1, 2, 3, 4, 5, 6, 7, 8, 9, 89, 135, 175, 518, 598, 1306, 1676, 2427];
        console.log(dis.filter(x => x <= n).join(" "));
    }
}
